from __future__ import annotations
from typing import List, Any

def flatten(nested_list: List[Any]) -> List[int]:
    """
    Flattens a nested list of integers of arbitrary depth.

    Complexity: O(n)

    >>> flatten([1, [2, [3, 4], 5], 6])
    [1, 2, 3, 4, 5, 6]
    """
    def _flatten(sublist: List[Any]) -> List[int]:
        result = []
        for item in sublist:
            if isinstance(item, list):
                result.extend(_flatten(item))
            else:
                result.append(item)
        return result

    return _flatten(nested_list)
