def group_by_key(lst: List[Dict[str, Any]], key: str, value_type: Optional[type] = None) -> Dict[Any, List[Dict[str, Any]]]:
    """
    Groups a list of dictionaries by the value of a given key.

    Complexity: O(n)

    >>> group_by_key([{'name': 'Alice', 'age': 30}, {'name': 'Bob', 'age': 30}], 'age')
    {30: [{'name': 'Alice', 'age': 30}, {'name': 'Bob', 'age': 30}]}
    >>> group_by_key([{'name': 'Alice', 'age': 30}, {'name': 'Bob', 'age': 30}], 'age', int)
    {30: [{'name': 'Alice', 'age': 30}, {'name': 'Bob', 'age': 30}]}
    """
    grouped = {}
    for item in lst:
        key_value = item[key]
        if value_type is not None and not isinstance(key_value, value_type):
            raise ValueError(f"Invalid type for key '{key}'. Expected {value_type.__name__}, got {type(key_value).__name__}.")
        if key_value not in grouped:
            grouped[key_value] = []
        grouped[key_value].append(item)
    return grouped
